// Top 3 students -> one certificate (HTML) per student, styled like the reference design

const rankLabels = ['1st', '2nd', '3rd'];
const rankTitles = ['First', 'Second', 'Third'];

const schoolName = 'Apollo International School';
const principalName = 'Mrs. Shah';

const esc = (v) =>
  String(v ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

const today = new Date().toLocaleDateString('en-GB', {
  day: 'numeric',
  month: 'long',
  year: 'numeric',
});

// In your sheet the "rank" column holds the marks (percentage)
const top3 = $input.all()
  .map((item) => item.json)
  .filter((s) => s['name'] && s['rank'] !== undefined && s['rank'] !== '')
  .sort((a, b) => Number(b['rank']) - Number(a['rank']))
  .slice(0, 3);

return top3.map((student, i) => {
  const name = esc(student['name']);
  const className = esc(student['class']);
  const percentage = esc(student['rank']);
  const email = student['gmail'] || '';
  const rank = i + 1;

  const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Certificate - ${name}</title>
<style>
  @page { size: A4 landscape; margin: 0; }
  body {
    margin: 0;
    padding: 20px;
    background: #eef0f4;
    font-family: 'Georgia', 'Times New Roman', serif;
  }
  .certificate {
    position: relative;
    width: 1000px;
    height: 700px;
    margin: auto;
    background: #fdfcf8;
    overflow: hidden;
    box-shadow: 0 0 25px rgba(0,0,0,0.15);
  }
  /* Ribbons */
  .ribbon {
    position: absolute;
    width: 500px;
    height: 500px;
    z-index: 1;
  }
  .ribbon.top-left { top: -250px; left: -250px; transform: rotate(45deg); }
  .ribbon.bottom-right { bottom: -250px; right: -250px; transform: rotate(45deg); }
  .ribbon .band {
    position: absolute;
    width: 100%;
    height: 90px;
    top: 205px;
  }
  .ribbon .navy { background: #14213d; height: 130px; top: 185px; }
  .ribbon .gold1 { background: linear-gradient(180deg,#e6c15c,#b8860b); height: 14px; top: 178px; }
  .ribbon .gold2 { background: linear-gradient(180deg,#b8860b,#e6c15c); height: 10px; top: 317px; }

  .border {
    position: absolute;
    inset: 22px;
    border: 2px solid #b8860b;
    z-index: 2;
    pointer-events: none;
  }
  .corner {
    position: absolute;
    width: 90px;
    height: 90px;
    border: 3px solid #b8860b;
    z-index: 3;
  }
  .corner.tl { top: 8px; left: 8px; border-right: none; border-bottom: none; }
  .corner.tr { top: 8px; right: 8px; border-left: none; border-bottom: none; }
  .corner.bl { bottom: 8px; left: 8px; border-right: none; border-top: none; }
  .corner.br { bottom: 8px; right: 8px; border-left: none; border-top: none; }

  .content {
    position: relative;
    z-index: 4;
    text-align: center;
    padding: 55px 90px 0;
  }
  .logo {
    width: 62px; height: 62px;
    margin: 0 auto 8px;
    border-radius: 50%;
    background: linear-gradient(145deg,#1a2a52,#0e1730);
    display: flex; align-items: center; justify-content: center;
    border: 3px solid #b8860b;
  }
  .logo svg { width: 34px; height: 34px; }
  .school-name {
    font-size: 15px;
    letter-spacing: 3px;
    color: #14213d;
    font-weight: bold;
    text-transform: uppercase;
    margin: 4px 0 2px;
  }
  .school-sub {
    font-size: 11px;
    letter-spacing: 2px;
    color: #b8860b;
    margin-bottom: 18px;
  }
  .title {
    font-size: 46px;
    letter-spacing: 4px;
    color: #14213d;
    text-transform: uppercase;
    margin: 0;
    font-weight: bold;
  }
  .subtitle {
    font-size: 17px;
    letter-spacing: 5px;
    color: #b8860b;
    text-transform: uppercase;
    margin: 4px 0 22px;
  }
  .presented {
    font-size: 13px;
    letter-spacing: 2px;
    color: #555;
    text-transform: uppercase;
    margin-bottom: 8px;
  }
  .name {
    font-family: 'Brush Script MT', 'Segoe Script', cursive;
    font-size: 48px;
    color: #14213d;
    border-bottom: 1px solid #b8860b;
    display: inline-block;
    padding: 0 40px 6px;
    margin-bottom: 18px;
  }
  .line1 {
    font-size: 12px;
    letter-spacing: 1.5px;
    color: #555;
    text-transform: uppercase;
    margin: 4px 0;
  }
  .course {
    font-size: 22px;
    letter-spacing: 2px;
    color: #14213d;
    font-weight: bold;
    text-transform: uppercase;
    margin: 2px 0 14px;
  }
  .achieve {
    font-size: 12px;
    letter-spacing: 1.5px;
    color: #555;
    text-transform: uppercase;
    margin: 4px 0;
  }
  .rank {
    font-size: 22px;
    letter-spacing: 2px;
    color: #14213d;
    font-weight: bold;
    text-transform: uppercase;
    margin: 2px 0 2px;
  }
  .marks {
    font-size: 14px;
    color: #555;
    margin-bottom: 10px;
  }

  .footer {
    position: relative;
    z-index: 4;
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    padding: 0 90px;
    margin-top: 10px;
  }
  .footer .block { width: 200px; text-align: center; }
  .footer .date-text {
    font-size: 12px;
    letter-spacing: 1px;
    color: #555;
    text-transform: uppercase;
    padding-top: 6px;
  }
  .footer .line {
    border-top: 1px solid #999;
    padding-top: 6px;
    font-size: 12px;
    letter-spacing: 1px;
    color: #555;
    text-transform: uppercase;
  }
  .seal {
    width: 90px; height: 90px;
    border-radius: 50%;
    background: radial-gradient(circle at 35% 30%, #f3d27a, #b8860b 70%, #8a6508);
    display: flex; align-items: center; justify-content: center;
    text-align: center;
    color: #14213d;
    font-size: 9px;
    font-weight: bold;
    letter-spacing: 1px;
    border: 3px solid #fdfcf8;
    box-shadow: 0 0 0 2px #b8860b;
    text-transform: uppercase;
  }
  .signature {
    font-family: 'Brush Script MT', 'Segoe Script', cursive;
    font-size: 32px;
    font-weight: bold;
    color: #1f3a93;
    margin-bottom: 4px;
  }
</style>
</head>
<body>
  <div class="certificate">
    <div class="ribbon top-left">
      <div class="band gold1"></div>
      <div class="band navy"></div>
      <div class="band gold2"></div>
    </div>
    <div class="ribbon bottom-right">
      <div class="band gold1"></div>
      <div class="band navy"></div>
      <div class="band gold2"></div>
    </div>

    <div class="border"></div>
    <div class="corner tl"></div>
    <div class="corner tr"></div>
    <div class="corner bl"></div>
    <div class="corner br"></div>

    <div class="content">
      <div class="logo">
        <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path d="M12 3L2 8l10 5 10-5-10-5z" fill="#e6c15c"/>
          <path d="M6 10.5V16c0 1.5 2.5 3 6 3s6-1.5 6-3v-5.5" stroke="#e6c15c" stroke-width="1.4" fill="none"/>
        </svg>
      </div>
      <div class="school-name">${schoolName}</div>
      <div class="school-sub">&bull; EXCELLENCE IN EDUCATION &bull;</div>

      <h1 class="title">Certificate</h1>
      <div class="subtitle">OF ACHIEVEMENT</div>

      <div class="presented">This certificate is proudly presented to</div>
      <div class="name">${name}</div>

      <div class="line1">For securing outstanding academic results in</div>
      <div class="course">Class ${className}</div>

      <div class="achieve">In recognition of</div>
      <div class="rank">${rankLabels[i]} Rank &mdash; ${rankTitles[i]} Position</div>
      <div class="marks">with <b>${percentage}%</b> marks</div>
    </div>

    <div class="footer">
      <div class="block">
        <div class="date-text">Date: ${today}</div>
      </div>
      <div class="seal">Official<br>Seal</div>
      <div class="block">
        <div class="signature">${principalName}</div>
        <div class="line">Principal's Signature</div>
      </div>
    </div>
  </div>
</body>
</html>`;

  return {
    json: {
      name: student['name'],
      className: student['class'],
      marks: student['rank'],
      email,
      rank,
      html,
    },
  };
});
